    'cdr_reports.help_body2' => 'Każdy wiersz to jedno połączenie: w kolumnie <b>Dzwoniący</b> trunk, którym przyszło, w kolumnie <b>Wybrany</b> trasa oraz – jeśli połączenie wyszło z centrali – trunk i wysłany numer; <b>Odebrane przez</b> to numer wewnętrzny, który przyjął połączenie. <b>Kierunek</b>: przychodzące, wychodzące, wewnętrzne lub trunk–trunk (przyszło jednym trunkiem i wyszło innym bez odebrania przez numer wewnętrzny AiPBX). Rozwiń wiersz, aby zobaczyć ścieżkę przekazanych połączeń. Filtrowanie według daty, statusu, numeru wewnętrznego, urządzenia, kierunku i trunku; odsłuchiwanie lub pobieranie nagrań.',
