    'asterisk_settings.rtp_section_title' => 'Ustawienia RTP (media)',
    'asterisk_settings.rtp_help_body' => 'Określa, który zakres portów przenosi dźwięk (RTP) i czy Asterisk odrzuca dźwięk przychodzący z nieoczekiwanego źródła. Ten plik (<code>/etc/asterisk/rtp.conf</code>) jest teraz generowany przez panel; ręczne zmiany na serwerze zostaną utracone przy następnym „Zastosuj”.',
    'asterisk_settings.field_rtp_start' => 'Port początkowy RTP',
    'asterisk_settings.rtp_start_help' => 'Początek zakresu portów zarezerwowanego dla strumieni audio. Każde jednoczesne połączenie zajmuje porty z tego zakresu.',
    'asterisk_settings.field_rtp_end' => 'Port końcowy RTP',
    'asterisk_settings.rtp_end_help' => 'Koniec zakresu. coturn (przekaźnik TURN) używa portów 13479-14999 – nakładanie się zakresów psuje dźwięk WebRTC i jest odrzucane przy zapisie.',
    'asterisk_settings.field_rtp_strict' => 'Strict RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Po włączeniu Asterisk po cichu odrzuca dźwięk przychodzący z innego źródła niż poznany zdalny adres/port (ochrona przed atakami). Jeśli centrala po drugiej stronie wysyła media z nieoczekiwanego portu, powoduje to cichy błąd „brak dźwięku” bez śladu w logach – na czas diagnozy można to tymczasowo wyłączyć.',
    'asterisk_settings.rtp_strict_yes' => 'Włączone (zalecane)',
    'asterisk_settings.rtp_strict_no' => 'Wyłączone (do diagnozy)',
    'asterisk_settings.rtp_restart_warning' => 'Ustawienie Strict RTP zaczyna obowiązywać po „Zastosuj”. Zmiana ZAKRESU PORTÓW wymaga jednak pełnego restartu Asterisk – pula portów jest przydzielana jednorazowo przy ładowaniu modułu.',
    'asterisk_settings.udptl_section_title' => 'Ustawienia T.38 UDPTL (media faksu)',
    'asterisk_settings.udptl_help_body' => 'Definiuje zakresy portów UDP i parametry korekcji błędów w przód (FEC / suma kontrolna) dla pakietów faksu T.38 (UDPTL). Ten plik (<code>/etc/asterisk/udptl.conf</code>) jest zarządzany dynamicznie.',
    'asterisk_settings.field_udptl_start' => 'Port początkowy UDPTL',
