    'asterisk_settings.field_udptl_checksums' => 'Sumy kontrolne UDPTL',
    'asterisk_settings.field_udptl_fec_entries' => 'Nadmiarowe wpisy FEC',
    'asterisk_settings.field_udptl_fec_span' => 'Rozpiętość FEC',
    'trunks.field_connection_mode' => 'Tryb połączenia',
    'trunks.connection_mode_ip' => 'Na podstawie IP (strona przeciwna ma stały IP)',
    'trunks.connection_mode_register' => 'Rejestracja przychodząca (strona przeciwna rejestruje się u nas)',
    'trunks.connection_mode_help' => 'Na podstawie IP: strona przeciwna jest identyfikowana po adresie IP, a jej kontakt jest statyczny – tryb zalecany dla strony ze stałym IP w tej samej sieci. Rejestracja przychodząca: strona przeciwna wysyła do nas SIP REGISTER, a jej adres jest ustalany na podstawie tej rejestracji. Ten tryb wymaga nazwy użytkownika i hasła; strona przeciwna uwierzytelnia nimi zarówno rejestrację, jak i połączenia.',
    'trunks.connection_mode_warning' => 'Przełączenie w tryb rejestracji usuwa statyczny kontakt: NIE można dzwonić do tego trunku, DOPÓKI strona przeciwna się u nas nie zarejestruje. Zmianę należy przeprowadzić równocześnie z ustawieniem rejestracji po stronie przeciwnej.',
    'ivr.entry_delete_confirm' => 'Usunąć routing dla klawisza %s?',
