    'ivr.entry_overwrite_warning' => 'Ten klawisz jest już przypisany – zapisanie nadpisze istniejący routing.',
    'sounds.moh_upload_title' => 'Prześlij muzykę w oczekiwaniu',
    'sounds.moh_upload_class' => 'Klasa muzyki',
    'sounds.moh_upload_file' => 'Plik audio',
    'sounds.moh_upload_file_help' => 'Przesłany plik jest automatycznie konwertowany do zgodnego z Asterisk formatu WAV.',
    'sounds.moh_upload_submit' => 'Prześlij',
    'sound_packs.tab' => 'Pakiety dźwięków Asterisk',
    'sound_packs.title' => 'Oficjalne pakiety dźwięków Asterisk',
    'sound_packs.help_title' => 'Pakiety dźwięków Asterisk',
    'sound_packs.help_body' => 'Pobiera i instaluje oficjalne komunikaty systemowe i muzykę w oczekiwaniu Asterisk z <code>downloads.asterisk.org</code>. Każdy pakiet to jeden język w jednym formacie; Asterisk odtwarza format pasujący do kodeka połączenia, a w przeciwnym razie transkoduje (g722 dla G.722, ulaw/alaw dla operatorów).<br>- <strong>Core:</strong> komunikaty systemowe, cyfry, poczta głosowa. <strong>Extra:</strong> dodatkowe komunikaty; najpierw musi być zainstalowany pakiet core tego samego języka.<br>- <strong>Muzyka w oczekiwaniu (opsound):</strong> instalowana w <code>/var/lib/asterisk/moh/opsound</code>; aby ją odtwarzać, utwórz klasę MOH o nazwie <strong>opsound</strong> na karcie Muzyka w oczekiwaniu.<br>- <strong>Türkçe (AiPBX):</strong> własne tureckie komunikaty AiPBX (wydanie GitHub, weryfikacja SHA256); domyślnym językiem jest turecki, więc ich usunięcie wycisza komunikaty systemowe. Usunięcie kasuje tylko pliki zainstalowane przez pakiet.',
