    'ms_teams.guide_title' => 'Przewodnik po integracji z Microsoft Teams',
    'ms_teams.guide_intro' => 'AiPBX może komunikować się z Microsoft Teams na dwóch różnych poziomach:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / trunk SIP):',
    'ms_teams.guide_dr_desc' => 'Umożliwia użytkownikom Teams wykonywanie i odbieranie połączeń wewnętrznych i zewnętrznych bezpośrednio z klawiatury Teams na komputerze/urządzeniu mobilnym. Wymaga TLS (port 5061), SRTP i ważnego publicznego certyfikatu SSL (np. Let\'s Encrypt).',
    'ms_teams.guide_webhook_title' => '2. Webhooki i powiadomienia kanałów:',
    'ms_teams.guide_webhook_desc' => 'Wysyła interaktywne karty Adaptive Cards do wskazanych kanałów Teams w przypadku nieodebranych połączeń, wiadomości poczty głosowej, faksów przychodzących i alertów call center. Nie wymaga licencji telefonicznych.',
    'ms_teams.guide_ps_title' => '3. Automatyczny generator PowerShell:',
    'ms_teams.guide_ps_desc' => 'Na karcie „Przewodnik PowerShell” można jednym kliknięciem automatycznie wygenerować polecenia PowerShell dostosowane do ustawień centrali, do uruchomienia w konsoli administratora Microsoft 365.',
