    'system_update.help_body' => 'Aktualizacja najpierw tworzy kopię zapasową bazy danych, ustawień i konfiguracji Asterisk, następnie instaluje nową wersję i sprawdza, czy wszystko działa. W razie niepowodzenia automatycznie przywraca poprzednią wersję. Podczas aktualizacji Asterisk jest restartowany: trwające połączenia zostają przerwane, dlatego aktualizacja nie rozpoczyna się, gdy trwają połączenia. Można ją też uruchomić na serwerze: <code>sudo aipbx-update</code>',
