    'certificates.header_title' => 'Certyfikat TLS',
    'certificates.help_title' => 'Przewodnik po certyfikatach',
    'certificates.help_body' => 'Portal (HTTPS), WebRTC TURNS i SIP-TLS/WSS korzystają z jednego certyfikatu; zmiany wprowadzone tutaj są stosowane jednocześnie w Apache, coturn i Asterisk. <b>Let\'s Encrypt</b> jest bezpłatny i odnawia się automatycznie; domena musi wskazywać na ten serwer, a port 80 musi być dostępny z internetu. Jeśli organizacja ma własny certyfikat, <b>prześlij go</b> (PEM lub PFX); przesłane certyfikaty nie odnawiają się automatycznie, należy przesłać nowy przed wygaśnięciem. Przy certyfikacie <b>samopodpisanym</b> przeglądarki wyświetlają ostrzeżenie, a TURNS nie działa w przeglądarkach: połączenia WebRTC za zaporami mogą nie mieć dźwięku.',
