    'queue_reports.title' => 'Centrum raportów kolejek',
    'queue_reports.help_title' => 'Przewodnik po raportach kolejek',
    'queue_reports.help_body' => 'Każde połączenie, które trafia do kolejki, jest liczone jeden raz. <b>Odebrane</b>: połączone z agentem. <b>Utracone</b>: dzwoniący rozłączył się podczas oczekiwania lub upłynął limit czasu kolejki. <b>Krótkie porzucenie</b>: rozłączenie w ciągu %d sekund; pomijane w poziomie obsługi. <b>Poziom obsługi</b>: połączenia odebrane w docelowym czasie w stosunku do wszystkich połączeń z wyjątkiem krótkich porzuceń. <b>ASA</b>: średni czas oczekiwania odebranych połączeń. <b>AHT</b>: średni czas rozmowy. <b>Wskaźnik odbioru</b> (agent): jak często agent odbierał, gdy kolejka do niego dzwoniła. <b>Oddzwonienie</b>: utracone połączenie uznaje się za rozwiązane, gdy później zadzwoniono na ten numer z numeru wewnętrznego lub numer zadzwonił ponownie i połączenie zostało odebrane. Dane pochodzą z dziennika kolejek Asterisk; raport można pobrać jako PDF lub Excel.',
