    'ai_tts.title' => 'Cloud TTS (synteza mowy)',
    'ai_tts.help_title' => 'Przewodnik Cloud TTS',
    'ai_tts.help_body' => 'Zamienia tekst na naturalną mowę za pomocą usług chmurowych (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Odsłuchaj wynik, pobierz go jako MP3 lub zapisz jednym kliknięciem jako <b>komunikat</b>: zostanie przekonwertowany do formatu Asterisk (8 kHz WAV) i dodany do Dźwięki &amp; komunikaty do użycia w IVR, trasach przychodzących i warunkach czasowych (działa po zastosowaniu). <b>Te usługi są płatne</b> i rozliczane za znak; każda synteza jest zapisywana w historii wraz z liczbą znaków. Klucze dostępu pochodzą z konsoli każdego dostawcy, są przechowywane w postaci zaszyfrowanej i nigdy nie są ponownie wyświetlane na stronie.',
    'ai_tts.tab_speak' => 'Synteza',
    'ai_tts.tab_providers' => 'Dostawcy',
    'ai_tts.providers_text' => 'Wprowadź dane dostępowe usług, z których chcesz korzystać. Klucze tajne są przechowywane w postaci zaszyfrowanej; pozostaw klucz pusty, aby zachować zapisany.',
    'ai_tts.configured' => 'Połączono',
