    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: włącz „Cloud Text-to-Speech API”; użyj klucza JSON konta usługi (IAM → Service Accounts → Keys → JSON) lub klucza API. Do %s znaków na żądanie; dłuższe teksty są dzielone.',
    'ai_tts.provider_hint_polly' => 'W AWS IAM utwórz klucz dostępu dla użytkownika, który ma tylko uprawnienia „polly:SynthesizeSpeech” i „polly:DescribeVoices”. Do %s znaków na żądanie.',
    'ai_tts.provider_hint_azure' => 'Utwórz zasób „Speech” w Azure Portal; klucz i region (np. westeurope) znajdują się na jego stronie „Keys and Endpoint”. Do %s znaków na żądanie.',
    'ai_tts.provider_hint_elevenlabs' => 'ElevenLabs → Profile → API Keys. Głosy pochodzą z biblioteki głosów konta i są wielojęzyczne. Do %s znaków na żądanie.',
