    'push.help_intro' => 'Mobilny softphone AI PBX ma <strong>warstwową architekturę powiadomień</strong>:',
    'push.help_layer0' => '<strong>Warstwa 0 (bez zależności - domyślna):</strong> stałe połączenie WSS, zgodna z Androidem 15 usługa pierwszoplanowa <code>specialUse</code> oraz odporny na tryb Doze watchdog <code>AlarmManager</code>, który ją wznawia. Żadna usługa zewnętrzna nie jest potrzebna; połączenia docierają nawet wtedy, gdy urządzenie jest bezczynne lub ekran jest wyłączony.',
    'push.help_layer1' => '<strong>Warstwa 1 (opcjonalna - Google FCM):</strong> dodatkowa gwarancja wybudzenia na urządzeniach producentów z agresywnymi ograniczeniami baterii (Xiaomi, Huawei...) lub gdy użytkownik zamknął aplikację przesunięciem. <em>Uruchamia się tylko wtedy, gdy numer wewnętrzny nie ma aktywnej rejestracji SIP, więc zarejestrowane numery wewnętrzne nie odczuwają opóźnienia.</em>',
    'push.help_no_fcm' => 'Jeśli FCM nie jest potrzebny, pozostaw dostawcę jako <strong>„Lokalny (bez zależności)”</strong>. Aplikacja mobilna nie nawiązuje wtedy żadnego kontaktu sieciowego z Google.',
