    'mailtpl.password_reset.body' => '<p>Witaj {name},</p><p>Zgłoszono prośbę o zresetowanie hasła do konta <strong>{username}</strong>.</p>{reset_button}<p>Jeśli przycisk nie działa, otwórz ten link: {reset_link}</p><p><em>Link jest ważny 30 minut. Jeśli nie zlecono tej prośby, zignoruj tę wiadomość; hasło pozostaje bez zmian.</em></p>',
    'mailtpl.voicemail.subject' => 'Nowa wiadomość głosowa od {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Witaj {name},</p><p>W skrzynce poczty głosowej <strong>{mailbox}</strong> jest nowa wiadomość.</p><ul><li><strong>Od:</strong> {caller}</li><li><strong>Otrzymano:</strong> {date}</li><li><strong>Długość:</strong> {duration}</li></ul><p>Jeśli nagranie jest załączone, można je odtworzyć bezpośrednio tutaj. Można je też odsłuchać w portalu ({portal_link}) lub wybierając *97.</p>',
    'mailtpl.fax_received.subject' => 'Odebrano nowy faks - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Odebrano nowy faks.</p><ul><li><strong>Jednostka:</strong> {department}</li><li><strong>Numer faksu:</strong> {did}</li><li><strong>Od:</strong> {caller}</li><li><strong>Strony:</strong> {pages}</li><li><strong>Otrzymano:</strong> {date}</li></ul><p>Faks jest dołączany jako PDF, gdy ta opcja jest włączona. Wszystkie faksy znajdują się w skrzynce odbiorczej faksów: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Faks dostarczony do {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Faks został dostarczony.</p><ul><li><strong>Do:</strong> {destination}</li><li><strong>Strony:</strong> {pages}</li><li><strong>Czas:</strong> {date}</li></ul><p>Wysłane faksy: {portal_link}</p>',
    'mailtpl.fax_failed.subject' => 'Faks NIE został dostarczony do {destination} (#{fax_id})',
    'mailtpl.fax_failed.body' => '<p>Nie udało się dostarczyć faksu.</p><ul><li><strong>Do:</strong> {destination}</li><li><strong>Strony:</strong> {pages}</li><li><strong>Czas:</strong> {date}</li><li><strong>Przyczyna:</strong> {error}</li></ul><p>Można go wysłać ponownie z portalu: {portal_link}</p>',
    'mailtpl.test.subject' => 'E-mail testowy {brand} ({date})',
    'mailtpl.test.body' => '<p>To jest e-mail testowy z <strong>{brand}</strong>. Jeśli można go przeczytać, wysyłanie e-maili działa.</p><ul><li><strong>Wysłano:</strong> {date}</li><li><strong>Od:</strong> {from_name} &lt;{from_address}&gt;</li><li><strong>Do:</strong> {to}</li><li><strong>Serwer:</strong> {host}</li></ul>',
